+              'target': {'id': 10},
+            },
+            {
+              'rel': 'x',
+              'source': {'id': 10},
+              'target': {'id': 11},
+            },
+          ],
+        });
+      }
+      final ids = (o.queryParameters['ids'] as String).split(',');
+      return jsonEncode({
+        'count': ids.length,
+        'value': [
+          for (final id in ids) {'id': int.parse(id), 'fields': {}},
+        ],
+      });
