+    expect(
+      extractWorkItemIds({
+        'workItemRelations': [
+          {
+            'rel': 'x',
+            'target': {'id': 4},
+          },
+          {
+            'rel': 'x',
+            'target': {'id': 4},
+          },
+        ],
+      }),
+      [4],
+    );
+  });
+}
+
+void _emptyShapes() {
